{
  "case_id": "xsu_sg_004_multiple_impairments",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer udgangspunktet (kun ansøgte funktionsnedsættelser) og samlet vurdering, men udelader helt, at en anden varig funktionsnedsættelse kan inddrages under sagens behandling, hvis ansøgeren ønsker det og indsender fyldestgørende dokumentation. Det rummer også en upræcis påstand om, at vurderingen sker ud fra 'aktuelle symptomer', og at samlet vurdering er 'for erhvervsevnen'. Derfor ikke fuldt korrekt og dækkende."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Tre af fire kritiske elementer er med: samlet vurdering, angivelse og dokumentation, og udgangspunktet om kun de ansøgte. Det fjerde mangler: senere inddragelse af en anden varig funktionsnedsættelse ved ønske og fyldestgørende dokumentation, der opfylder minimumskravene. Journalomtale alene er heller ikke nævnt."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvilke funktionsnedsættelser Udbetaling Danmark vurderer: de ansøgte, og hvis der er flere, samlet. Det er ikke erstattet af irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver Vejledning nr. 10157 af 5. oktober 2026 (VEJ nr. 10157), som er en identificerbar kilde. Det bruger desuden fodnotelignende henvisninger 1-3. Henvisningerne er dog ikke knyttet til konkrete afsnit."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning nr. 10157 om handicaptillæg findes i de frosne kilder og er autoritativ og anvendelig. Kildelisten indeholder dog en løs sætning uden kildeangivelse."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Udgangspunktet (3.5) og samlet vurdering (3.4.1.2) støttes. Påstanden om, at vurderingen af 'de aktuelle symptomer' sker 'individuelt', og at den samlede vurdering gælder 'betydningen for erhvervsevnen', støttes ikke direkte af de angivne passager. Påstanden om, at ansøgeren 'bør' dokumentere, er en svækket gengivelse af et krav. Henvisningerne peger desuden kun på numre, ikke konkrete passager."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at vurderingen sker ud fra 'de aktuelle symptomer, som er beskrevet i materialet'. Det har ikke direkte støtte i de udleverede passager, som taler om dokumentation, der er aktuel i forhold til funktionsnedsættelserne. Formuleringen 'Mest nærliggende svar' og 'Foreløbig konklusion' er upræcis, men ikke en retsregel."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Udgangspunktet er bevaret ('som udgangspunkt'). Undtagelsen er udeladt: senere inddragelse af en anden funktionsnedsættelse kræver ønske, fyldestgørende dokumentation og opfyldte minimumskrav. Det er en påkrævet kvalifikation. Journalomtale alene er ikke tilstrækkelig, og det er heller ikke nævnt."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "De synlige trin hænger sammen: kun ansøgte funktionsnedsættelser vurderes, flere vurderes samlet, og ansøgeren bør angive og dokumentere. Konklusionen følger heraf. Svaret er ufuldstændigt, men ikke selvmodsigende."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "'Som udgangspunkt' gengives korrekt. Men kilden siger, at ansøgeren 'skal' angive funktionsnedsættelserne og indsende dokumentation. Svaret skriver 'bør', hvilket gør et krav til en anbefaling."
    }
  },
  "xhaile_coverage": {
    "A16": {
      "label": "yes",
      "reason": "Svaret siger, at flere funktionsnedsættelser vurderes samlet, og at dokumentation for dem skal indsendes (formuleret som 'bør'). Kernen om samlet vurdering er dækket."
    },
    "A24": {
      "label": "partial",
      "reason": "Udgangspunktet om, at kun de ansøgte funktionsnedsættelser vurderes, og at ansøgeren skal angive dem, er med. Eksemplet om, at andre journalnævnte funktionsnedsættelser ikke vurderes, mangler, og kravet er blødgjort til 'bør'."
    },
    "A25": {
      "label": "no",
      "reason": "Svaret nævner ikke, at en ny varig funktionsnedsættelse kan inddrages under sagens behandling på ansøgerens initiativ, hvis ansøgeren ønsker det og indsender fyldestgørende dokumentation, der opfylder minimumskravene."
    }
  },
  "overall_notes": "Svaret er kort og i hovedsagen korrekt om udgangspunktet og den samlede vurdering. Det udelader den vigtigste undtagelse (senere inddragelse af andre funktionsnedsættelser), blødgør 'skal' til 'bør' og tilføjer en ikke-understøttet henvisning til 'aktuelle symptomer'. Kildeangivelsen er identificerbar, men upræcis."
}

